<?php require_once __DIR__.'/bootstrap.php';requireUser();header('Content-Type: text/event-stream');header('Cache-Control: no-cache');header('X-Accel-Buffering: no');$last='';for($i=0;$i<25;$i++){ $s=db()->query("SELECT GREATEST(COALESCE(MAX(updated_at),'1970-01-01'),(SELECT COALESCE(MAX(created_at),'1970-01-01') FROM notifications)) stamp FROM tasks");$stamp=(string)$s->fetch()['stamp'];if($stamp!==$last){echo "event: tasks\ndata: ".json_encode(['updated_at'=>$stamp])."\n\n";echo "event: notifications\ndata: {}\n\n";ob_flush();flush();$last=$stamp;}sleep(2);}
